#!/usr/bin/env tsx
/**
 * Generate Shell-Completion Target Sets
 *
 * The `sentry __complete` fast path (src/lib/complete.ts) skips the Stricli
 * boot, so it cannot walk the route tree at runtime to decide which commands
 * complete org or org/project slugs. This script walks the route tree at build
 * time, collects every command that declares `completionTarget` in
 * `buildCommand()`, and writes the result as a static module.
 *
 * The output is gitignored and regenerated by `generate:docs`, which runs as
 * part of `dev`, `build`, `bundle`, `typecheck`, and `test`.
 *
 * Usage:   tsx script/generate-completion-targets.ts
 * Output:  src/generated/completion-targets.ts
 */

import { mkdirSync } from "node:fs";
import { access, writeFile } from "node:fs/promises";

// Bootstrap: skill-content stub (same pattern as generate-command-docs.ts).
// The route tree transitively imports skill-content.ts, which may not exist
// yet on a fresh checkout. Must run before the dynamic import below.
const SKILL_CONTENT_PATH = "src/generated/skill-content.ts";
const SKILL_CONTENT_STUB =
  "export const SKILL_FILES: [string, string][] = [];\n";
const skillContentExists = await access(SKILL_CONTENT_PATH).then(
  () => true,
  () => false,
);
if (!skillContentExists) {
  mkdirSync("src/generated", { recursive: true });
  await writeFile(SKILL_CONTENT_PATH, SKILL_CONTENT_STUB);
}

import type { RouteMap } from "../src/lib/introspect.js";

const { routes } = await import("../src/app.js");
const { extractCompletionTargets } = await import("../src/lib/introspect.js");

const OUTPUT_PATH = "src/generated/completion-targets.ts";

/** Render a sorted path list as a `ReadonlySet<string>` literal. */
function renderSet(name: string, doc: string, paths: string[]): string {
  const items = paths.map((path) => `  ${JSON.stringify(path)},`).join("\n");
  return `/** ${doc} */\nexport const ${name}: ReadonlySet<string> = new Set([\n${items}\n]);\n`;
}

const targets = extractCompletionTargets(routes as unknown as RouteMap);

const module = `// AUTO-GENERATED by script/generate-completion-targets.ts — DO NOT EDIT.
// Regenerate with: pnpm run generate:completions
// Source of truth: \`completionTarget\` on each command's buildCommand() call.

${renderSet(
  "ORG_PROJECT_COMMANDS",
  "Commands whose target positional completes `org/project` slugs and aliases.",
  targets["org/project"],
)}
${renderSet(
  "ORG_ONLY_COMMANDS",
  "Commands whose target positional completes organization slugs only.",
  targets.org,
)}`;

mkdirSync("src/generated", { recursive: true });
await writeFile(OUTPUT_PATH, module, "utf8");
process.stdout.write(
  `Wrote ${OUTPUT_PATH} (${targets["org/project"].length} org/project, ${targets.org.length} org-only)\n`,
);
